import Link from 'next/link'
import { useEffect, useState } from 'react'
import {
  getCertifications,
  getChapters,
} from '@/lib/supabase/queries'
import type {
  Certification,
  Chapter,
} from '@/types/database'

const options = [
  {
    number: '01',
    title: 'Full mock exam',
    description: 'Take a timed, full-length simulation with the structure and challenge of the real certification exam.',
    href: '/practice/full',
    link: 'Start full exam',
  },
  {
    number: '02',
    title: 'Practice by chapter',
    description: 'Concentrate on one syllabus chapter, identify weak areas and strengthen your understanding.',
    href: '/practice/chapter',
    link: 'Choose a chapter',
  },
  {
    number: '03',
    title: 'Practice by learning objective',
    description: 'Select a specific learning objective inside a chapter and practise exactly what you need.',
    href: '/practice/objective',
    link: 'Choose an objective',
  },
]

export function PracticeSelector() {
  const [certifications, setCertifications] = useState<Certification[]>([])
  const [chapters, setChapters] = useState<Chapter[]>([])
  const [certificationId, setCertificationId] = useState('')
  const [chapterId, setChapterId] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    getCertifications()
      .then(setCertifications)
      .catch(() => setError('Could not load certifications.'))
      .finally(() => setLoading(false))
  }, [])

  useEffect(() => {
    setChapters([])
    setChapterId('')

    if (!certificationId) return

    getChapters(Number(certificationId))
      .then(setChapters)
      .catch(() => setError('Could not load chapters.'))
  }, [certificationId])

  if (loading) {
    return <p>Loading certifications…</p>
  }

  return (
    <section className="practiceSelector">
      <label>
        Certification

        <select
          value={certificationId}
          onChange={(event) => setCertificationId(event.target.value)}
        >
          <option value="">Select certification</option>

          {certifications.map((certification) => (
            <option key={certification.id} value={certification.id}>
              {certification.id} — {certification.name}
            </option>
          ))}
        </select>
      </label>

      <label>
        Chapter

        <select
          value={chapterId}
          disabled={!certificationId}
          onChange={(event) => setChapterId(event.target.value)}
        >
          <option value="">Select chapter</option>

          {chapters.map((chapter) => (
            <option key={chapter.id} value={chapter.id}>
              Chapter {chapter.chapter_number}: {chapter.chapter_name}
            </option>
          ))}
        </select>
      </label>

      {error && <p role="alert">{error}</p>}

      <button type="button" disabled={!chapterId}>
        Start chapter practice
      </button>
    </section>
  )
}
